package com.dorm.fourchess;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Native, scrollable phone-first career pages sharing the game's portraits and courtyard. */
final class ArchiveCenter extends LinearLayout {
    private final Activity host;private final PlayerArchive store;private final ArchiveCloud cloud;private final Runnable leave;
    private LinearLayout body;private String tab="棋士档案";private final String[] tabs={"棋士档案","万象荣誉录","棋友录","角色羁绊","棋士衣橱","棋局战绩","棋士生涯","账号与云存档"};
    private final int gold=0xffe4c991,white=0xffedf1ec,muted=0xffa8bbc4;
    ArchiveCenter(Activity h,PlayerArchive s,ArchiveCloud c,Runnable close){super(h);host=h;store=s;cloud=c;leave=close;setOrientation(VERTICAL);setBackground(new CourtyardScene());setPadding(dp(12),dp(6),dp(12),dp(8));render();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String value,int size,int color){TextView v=new TextView(host);v.setText(value);v.setTextColor(color);v.setTextSize(size);v.setTypeface(GameDesign.BODY);v.setPadding(dp(3),dp(5),dp(3),dp(5));return v;}
    private android.graphics.drawable.Drawable panel(int fill){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(8));d.setStroke(dp(1),0x607b8d91);return d;}
    private Button action(String label,Runnable run){Button b=new Button(host);b.setElevation(0);b.setStateListAnimator(null);b.setText(label);b.setTextColor(gold);b.setTextSize(13);b.setAllCaps(false);b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setPadding(dp(10),dp(7),dp(10),dp(7));b.setBackground(panel(0xd51b3444));b.setOnClickListener(v->attempt(run));return b;}
    private void attempt(Runnable run){try{run.run();}catch(Exception e){message(e.getMessage()==null?"操作失败":e.getMessage());}}
    private void message(String m){Toast.makeText(host,m,Toast.LENGTH_LONG).show();}
    private interface Job{void run()throws Exception;}
    private void job(Job r){try{r.run();}catch(Exception e){message(e.getMessage()==null?"数据操作失败":e.getMessage());}}
    void render(){removeAllViews();LinearLayout header=new LinearLayout(host);header.setGravity(Gravity.CENTER_VERTICAL);Button back=action("返回游戏",leave);header.addView(back,new LinearLayout.LayoutParams(-2,dp(44)));TextView brand=text("棋 士 行 纪",20,gold);brand.setGravity(Gravity.CENTER);header.addView(brand,new LinearLayout.LayoutParams(0,dp(48),1));Button account=action("切换",this::chooseArchive);header.addView(account,new LinearLayout.LayoutParams(-2,dp(44)));addView(header);
        HorizontalScrollView strip=new HorizontalScrollView(host);strip.setHorizontalScrollBarEnabled(false);LinearLayout items=new LinearLayout(host);for(String name:tabs){Button b=action(name,()->{tab=name;render();});b.setSelected(name.equals(tab));b.setTextColor(name.equals(tab)?0xffffe1a2:muted);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.setMargins(0,dp(5),dp(5),dp(5));items.addView(b,p);}strip.addView(items);addView(strip,new LinearLayout.LayoutParams(-1,dp(54)));
        ScrollView scroller=new ScrollView(host);scroller.setFillViewport(false);body=new LinearLayout(host);body.setOrientation(VERTICAL);body.setPadding(dp(7),dp(10),dp(7),dp(16));body.setBackground(panel(0xe60f2432));scroller.addView(body);addView(scroller,new LinearLayout.LayoutParams(-1,0,1));
        job(()->{JSONObject d=store.current();if(d==null){heading("一卷棋士档案，记录你的四方征途");paragraph("可创建仅保存在本机的棋士档案，或使用临时游客。云端服务配置后，可注册并跨设备恢复。");button("创建本地棋士档案",()->create(false));button("进入本地游客模式",()->create(true));accountPage(null);return;}switch(tab){case "万象荣誉录":achievements(d);break;case "棋友录":friends(d);break;case "角色羁绊":characters(d);break;case "棋士衣橱":wardrobe(d);break;case "棋局战绩":statistics(d);break;case "棋士生涯":timeline(d);break;case "账号与云存档":accountPage(d);break;default:profile(d);}});
    }
    private void heading(String s){TextView t=text(s,18,gold);t.setTypeface(GameDesign.EMPHASIS);body.addView(t);}
    private void paragraph(String s){body.addView(text(s,13,white));}
    private void note(String s){body.addView(text(s,12,muted));}
    private void button(String title,Runnable r){Button b=action(title,r);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(3));body.addView(b,p);}
    private JSONObject current()throws Exception{JSONObject d=store.current();if(d==null)throw new IllegalStateException("请先选择档案");return d;}
    private String date(long t){return t<=0?"—":new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.CHINA).format(new Date(t));}
    private void progress(int n,int max){ProgressBar p=new ProgressBar(host,null,android.R.attr.progressBarStyleHorizontal);p.setMax(Math.max(1,max));p.setProgress(Math.min(max,n));p.setProgressTintList(android.content.res.ColorStateList.valueOf(gold));body.addView(p,new LinearLayout.LayoutParams(-1,dp(10)));}
    private void profile(JSONObject d){JSONObject p=CareerRules.object(d,"profile"),s=CareerRules.object(d,"statistics");String title=CareerRules.object(d,"outfit").optString("title","auto");String label=title.startsWith("hero")?CareerRules.HEROES[Integer.parseInt(title.substring(4))]+" · 知音":CareerRules.title(d.optInt("level",1));body.addView(new PortraitBanner(d),new LinearLayout.LayoutParams(-1,dp(154)));heading(p.optString("nickname")+"   LV."+d.optInt("level",1));paragraph(label+(d.optBoolean("guest")?" · 游客（不计正式战绩）":""));note("棋士ID  "+d.optString("id"));paragraph(p.optString("bio").isEmpty()?"一子落定，四方知音。":p.optString("bio"));long xp=d.optLong("xp");int level=d.optInt("level",1);paragraph("修行经验 "+xp+(level>=100?" · 已满级":" · 本级 "+CareerRules.progress(xp)+" / "+CareerRules.need(level)));progress(level==100?1:(int)CareerRules.progress(xp),level==100?1:CareerRules.need(level));paragraph("对局 "+s.optInt("games")+"    获胜 "+s.optInt("wins")+"    最长连胜 "+s.optInt("best"));JSONArray badges=CareerRules.array(d,"badges");StringBuilder marks=new StringBuilder("展示徽章  ");for(int i=0;i<badges.length();i++)for(CareerRules.Achievement a:CareerRules.ACHIEVEMENTS)if(a.id.equals(badges.optString(i)))marks.append("「").append(a.name).append("」 ");note(marks.toString());LinearLayout badgeRow=new LinearLayout(host);for(int i=0;i<badges.length();i++)for(CareerRules.Achievement a:CareerRules.ACHIEVEMENTS)if(a.id.equals(badges.optString(i)))badgeRow.addView(new HonorSeal(a,true),new LinearLayout.LayoutParams(dp(62),dp(62)));if(badges.length()>0)body.addView(badgeRow);button("编辑昵称与个人介绍",()->edit(d));button("展示最多三个成就徽章",()->chooseBadges(d));button("复制我的棋友名片",()->copyCard(d));ArrayList<JSONObject> matches=CareerRules.orderedMatches(d);if(!matches.isEmpty()){heading("最近表现");for(int i=matches.size()-1;i>=Math.max(0,matches.size()-3);i--)matchLine(matches.get(i));}}
    private void create(boolean guest){EditText name=input("棋士昵称（最多12字）",false);dialog(guest?"本地游客":"创建本地棋士",new EditText[]{name},()->{store.create(name.getText().toString(),guest);render();});}
    private void chooseArchive(){ArrayList<JSONObject> list=store.list();String[] labels=new String[list.size()+2];for(int i=0;i<list.size();i++){JSONObject d=list.get(i);labels[i]=CareerRules.object(d,"profile").optString("nickname")+" · "+(d.optBoolean("guest")?"游客":"LV."+d.optInt("level",1));}labels[list.size()]="新建本地棋士";labels[list.size()+1]="新建临时游客";new AlertDialog.Builder(host).setTitle("选择本机档案 · 不自动联网").setItems(labels,(a,index)->{if(index>=list.size())create(index==list.size()+1);else{store.select(list.get(index).optString("id"));render();}}).setNegativeButton("取消",null).show();}
    private EditText input(String hint,boolean secret){EditText e=new EditText(host);e.setHint(hint);e.setTextColor(white);e.setHintTextColor(muted);e.setTextSize(14);e.setMinHeight(dp(48));e.setSingleLine(true);if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);return e;}
    private void dialog(String title,EditText[] fields,Job save){LinearLayout content=new LinearLayout(host);content.setOrientation(VERTICAL);content.setPadding(dp(16),dp(8),dp(16),dp(8));content.setBackgroundColor(0xff122b3b);for(EditText f:fields)content.addView(f,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(host);scroll.addView(content);AlertDialog a=new AlertDialog.Builder(host).setTitle(title).setView(scroll).setNegativeButton("取消",null).setPositiveButton("确认",null).create();a.show();GameDialogStyle.apply(a,content);a.getButton(-1).setOnClickListener(v->{try{save.run();a.dismiss();}catch(Exception e){message(e.getMessage());}});}
    private void edit(JSONObject d){EditText name=input("昵称",false),bio=input("个人介绍（160字内）",false);name.setText(CareerRules.object(d,"profile").optString("nickname"));bio.setText(CareerRules.object(d,"profile").optString("bio"));dialog("修改棋士资料",new EditText[]{name,bio},()->{store.edit(d.getString("id"),name.getText().toString(),bio.getText().toString(),CareerRules.object(d,"profile").optInt("avatar"));render();});}
    private void chooseBadges(JSONObject d){ArrayList<CareerRules.Achievement> list=new ArrayList<>();for(CareerRules.Achievement a:CareerRules.ACHIEVEMENTS)if(CareerRules.object(CareerRules.object(d,"achievements"),a.id).optBoolean("unlocked"))list.add(a);if(list.isEmpty()){message("尚无已解锁的成就");return;}boolean[] chosen=new boolean[list.size()];JSONArray current=CareerRules.array(d,"badges");String[] names=new String[list.size()];for(int i=0;i<list.size();i++){names[i]=list.get(i).name;for(int j=0;j<current.length();j++)if(current.optString(j).equals(list.get(i).id))chosen[i]=true;}new AlertDialog.Builder(host).setTitle("展示徽章 · 最多三个").setMultiChoiceItems(names,chosen,(a,i,on)->chosen[i]=on).setPositiveButton("保存",(a,w)->job(()->{JSONArray result=new JSONArray();for(int i=0;i<chosen.length;i++)if(chosen[i])result.put(list.get(i).id);store.badges(d.getString("id"),result);render();})).setNegativeButton("取消",null).show();}
    private void achievements(JSONObject d){heading("万 象 荣 誉 录");note("挑战首次达成自动领取经验与徽章；重复结算不会再次领奖。隐藏成就解锁前隐藏名称。");JSONObject all=CareerRules.object(d,"achievements");for(CareerRules.Achievement a:CareerRules.ACHIEVEMENTS){JSONObject state=CareerRules.object(all,a.id);boolean done=state.optBoolean("unlocked");String name="隐藏".equals(a.category)&&!done?"未解之谜":a.name;LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(new HonorSeal(a,done),new LinearLayout.LayoutParams(dp(52),dp(52)));row.addView(text(name+"  · "+a.quality+" / "+a.category,14,done?gold:muted),new LinearLayout.LayoutParams(0,-2,1));body.addView(row);note(("隐藏".equals(a.category)&&!done?"继续探索四象之道":condition(a))+"   "+state.optInt("progress")+" / "+a.target);progress(state.optInt("progress"),a.target);note(done?"已领取："+a.bonus+"经验与专属徽章 · "+date(state.optLong("at")):"首次奖励："+a.bonus+"经验与专属徽章");}}
    private String condition(CareerRules.Achievement a){String[] keys={"games","wins","best","captures","skills","secret","friendGames","intimacy","friends","sides","classicWins","minutes","bondMax"},names={"累计有效对局","累计获胜","最高连胜","累计吃子","使用秘术","秘术模式对局","与好友共同完成对局","最高好友亲密度","添加棋友","使用不同阵营完成对局","普通模式胜利","累计对局分钟","最高角色羁绊等级"};for(int i=0;i<keys.length;i++)if(keys[i].equals(a.metric))return names[i]+"达到"+a.target;return a.name;}
    private void friends(JSONObject d){heading("棋 友 录");note("只显示真实本地记录；不提供虚构在线状态。交换名片为自报身份，不代表云端认证。");button("添加本机棋士为棋友",()->{ArrayList<JSONObject> list=store.list();for(Iterator<JSONObject> it=list.iterator();it.hasNext();)if(it.next().optString("id").equals(d.optString("id")))it.remove();String[] labels=new String[list.size()];for(int i=0;i<list.size();i++)labels[i]=CareerRules.object(list.get(i),"profile").optString("nickname");new AlertDialog.Builder(host).setTitle("选择本机档案").setItems(labels,(a,i)->job(()->{store.addFriend(d.getString("id"),PlayerArchive.card(list.get(i)));render();})).setNegativeButton("取消",null).show();});button("粘贴棋友名片 / 局域网交换名片",()->{EditText card=input("粘贴棋友JSON名片",false);dialog("添加交换名片",new EditText[]{card},()->{String value=card.getText().toString();if(value.length()>2048)throw new Exception("名片过大");store.addFriend(d.getString("id"),new JSONObject(value));render();});});button("复制我的棋友名片",()->copyCard(d));JSONObject friends=CareerRules.object(d,"friends");Iterator<String> keys=friends.keys();if(!keys.hasNext())paragraph("棋友录尚空，邀一位知音入局吧。");while(keys.hasNext()){String id=keys.next();JSONObject f=friends.optJSONObject(id),s=CareerRules.object(CareerRules.object(d,"friendStats"),id);button(f.optString("nickname")+" · LV."+f.optInt("level",1)+" · "+CareerRules.friendship(s.optInt("intimacy")),()->friendDetail(d,f,s));}}
    private void friendDetail(JSONObject d,JSONObject f,JSONObject s){String id=f.optString("id");StringBuilder shared=new StringBuilder();ArrayList<JSONObject> matches=CareerRules.orderedMatches(d);for(int i=matches.size()-1;i>=0;i--)if(matches.get(i).optJSONArray("players").toString().contains(id))shared.append(date(matches.get(i).optLong("ended"))).append(" · ").append("win".equals(matches.get(i).optString("result"))?"本方胜利":"本方落败").append('\n');LinearLayout faces=new LinearLayout(host);faces.setOrientation(VERTICAL);faces.setPadding(dp(12),dp(8),dp(12),dp(8));faces.setBackgroundColor(0xff152d3a);JSONObject friendDoc=new JSONObject(),friendProfile=new JSONObject();CareerRules.put(friendProfile,"avatar",f.optInt("avatar"));CareerRules.put(friendProfile,"nickname",f.optString("nickname"));CareerRules.put(friendDoc,"profile",friendProfile);JSONObject friendOutfit=new JSONObject();CareerRules.put(friendOutfit,"frame","plain");CareerRules.put(friendDoc,"outfit",friendOutfit);faces.addView(new PortraitBanner(d),new LinearLayout.LayoutParams(-1,dp(94)));faces.addView(new PortraitBanner(friendDoc),new LinearLayout.LayoutParams(-1,dp(94)));ProgressBar bond=new ProgressBar(host,null,android.R.attr.progressBarStyleHorizontal);int intimacy=s.optInt("intimacy"),target=50;for(int floor:new int[]{50,150,400,800,1500,3000})if(intimacy>=floor)target=floor==3000?3000:floor==50?150:floor==150?400:floor==400?800:floor==800?1500:3000;bond.setMax(target);bond.setProgress(Math.min(target,intimacy));faces.addView(bond,new LinearLayout.LayoutParams(-1,dp(12)));
        new AlertDialog.Builder(host).setView(faces).setTitle(f.optString("nickname")+" · "+CareerRules.friendship(s.optInt("intimacy"))).setMessage("棋士ID："+id+"\n备注："+f.optString("note")+"\n等级称号："+CareerRules.title(f.optInt("level",1))+"\n亲密度："+s.optInt("intimacy")+"\n共同对局："+s.optInt("games")+"\n成为棋友："+date(f.optLong("since"))+"\n最近同局："+date(s.optLong("last"))+"\n关系徽章："+CareerRules.friendship(s.optInt("intimacy"))+"\n\n"+shared).setPositiveButton("修改备注",(a,w)->{EditText e=input("备注（24字内）",false);e.setText(f.optString("note"));dialog("棋友备注",new EditText[]{e},()->{store.note(d.getString("id"),id,e.getText().toString());render();});}).setNeutralButton("移出棋友录",(a,w)->new AlertDialog.Builder(host).setMessage("确认移出？本地羁绊显示将消失，历史对局保留。").setPositiveButton("确认移出",(b,v)->job(()->{store.removeFriend(d.getString("id"),id);render();})).setNegativeButton("取消",null).show()).setNegativeButton("关闭",null).show();}
    private void copyCard(JSONObject d){android.content.ClipboardManager clipboard=(android.content.ClipboardManager)host.getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("四象棋尊棋友名片",PlayerArchive.card(d).toString()));message("已复制公开名片，不含密码、令牌或私人档案");}
    private void characters(JSONObject d){heading("四 象 羁 绊");note("有效对局+20角色经验，获胜再+10；上限LV.20，仅解锁外观与故事，不改变棋子能力。");for(int i=0;i<4;i++){final int hero=i;JSONObject state=CareerRules.object(CareerRules.object(d,"characters"),""+i);int level=state.optInt("level",1);paragraph(CareerRules.HEROES[i]+" · LV."+level+" / 20");note("累计羁绊经验 "+state.optLong("xp")+" · LV.2解锁角色壁纸与知音称号");button("阅读 · "+CareerRules.HEROES[i],()->new AlertDialog.Builder(host).setTitle(CareerRules.HEROES[hero]).setMessage(new String[]{"以赤焰守护落子之约，宁可失一城，不负一知音。","落花与棋声相伴，她相信每次相遇都能留下新的棋谱。","月下的白发棋士，收藏着四方旅人的未尽之局。","金风拂过庭院，她与白猫等候下一位问道的棋友。"}[hero]+(level>=20?"\n\n羁绊圆满 · 此后四方皆是归处。":"\n\n达到LV.20解锁羁绊终章。")).setPositiveButton("合卷",null).show());}note("当前素材未包含角色语音、独立表情及透明半身立绘，因此不会展示无效的语音/立绘奖励入口。可补充相应资源后扩展。");}
    private void wardrobe(JSONObject d){heading("棋 士 衣 橱");note("所有装扮仅改变显示。选择后立即应用于本机界面；奖励来源可在下方查看。");String[] kinds={"avatar","frame","wall","card","title","board","piece","effect"},labels={"角色头像","头像框","主页壁纸","名片背景","展示称号","棋盘皮肤","棋子皮肤","落子特效"};JSONArray unlocked=CareerRules.array(d,"unlocked");for(int k=0;k<kinds.length;k++){final String kind=kinds[k];button(labels[k]+" · "+equipped(d,kind),()->{ArrayList<String> ids=new ArrayList<>();for(int n=0;n<unlocked.length();n++){String v=unlocked.optString(n);if(v.startsWith(kind+":"))ids.add(v.substring(kind.length()+1));}String[] options=new String[ids.size()];for(int n=0;n<ids.size();n++)options[n]=itemName(kind,ids.get(n));new AlertDialog.Builder(host).setTitle(labelsFor(kind)).setItems(options,(a,i)->job(()->{String value=ids.get(i);if(kind.equals("avatar")){JSONObject p=CareerRules.object(d,"profile");store.edit(d.getString("id"),p.optString("nickname"),p.optString("bio"),Integer.parseInt(value));}else store.equip(d.getString("id"),kind,value);render();})).setNegativeButton("取消",null).show();});}body.addView(new PortraitBanner(d),new LinearLayout.LayoutParams(-1,dp(142)));note("默认：四位头像与基础皮肤\nLV.10：鎏金框、青玉棋盘\nLV.20：玉石棋子、水墨落子\n传说成就：尊享框\n角色羁绊LV.2：对应壁纸、称号\n棋友亲密度400：玉缘框、名片背景");}
    private String labelsFor(String k){return "选择已解锁装扮 · "+k;}
    private String equipped(JSONObject d,String k){return itemName(k,k.equals("avatar")?""+CareerRules.object(d,"profile").optInt("avatar"):CareerRules.object(d,"outfit").optString(k));}
    private String itemName(String kind,String v){if(kind.equals("avatar"))return CareerRules.HEROES[Integer.parseInt(v)];if(v.startsWith("hero"))return CareerRules.HEROES[Integer.parseInt(v.substring(4))];switch(v){case "plain":return "素金";case "night":return "月夜庭院";case "ivory":return "象牙古棋";case "quiet":return "清雅落子";case "gold":return "鎏金";case "jade":return "苍翠玉纹";case "legend":return "万象尊享";case "ink":return "水墨涟漪";default:return "等级称号";}}
    private void statistics(JSONObject d){JSONObject s=CareerRules.object(d,"statistics");heading("棋 局 战 绩");int games=s.optInt("games"),wins=s.optInt("wins");paragraph("总对局 "+games+"   胜 "+wins+"   负 "+s.optInt("losses")+"   平 0");paragraph("胜率 "+(games==0?"—":String.format(Locale.CHINA,"%.1f%%",wins*100f/games))+"   当前连胜 "+s.optInt("streak")+"   最长连胜 "+s.optInt("best"));paragraph("累计吃子 "+s.optInt("captures")+"   秘术 "+s.optInt("skills")+"   好友共同对局 "+s.optInt("friendGames"));JSONArray modes=CareerRules.array(s,"modeTotals");for(int mode=0;mode<2;mode++)note((mode==0?"普通":"秘术")+"模式："+modes.optInt(mode*2)+"局 / "+modes.optInt(mode*2+1)+"胜 · 胜率"+rate(modes.optInt(mode*2+1),modes.optInt(mode*2)));JSONArray sides=CareerRules.array(s,"sideGames"),sideWins=CareerRules.array(s,"sideWins");for(int i=0;i<4;i++)note(CareerRules.HEROES[i]+"："+sides.optInt(i)+"局 / "+sideWins.optInt(i)+"胜 · 胜率"+rate(sideWins.optInt(i),sides.optInt(i)));int favorite=-1;for(int i=0;i<4;i++)if(sides.optInt(i)>0&&(favorite<0||sides.optInt(i)>sides.optInt(favorite)))favorite=i;note("常用阵营："+(favorite<0?"尚无有效对局":CareerRules.HEROES[favorite]));note("原规则只有最终存活者获胜；不虚构平局或其他名次。退出未结束对局不计正式结算。");ArrayList<JSONObject> matches=CareerRules.orderedMatches(d);heading("最近10局");for(int i=matches.size()-1;i>=Math.max(0,matches.size()-10);i--)matchLine(matches.get(i));if(matches.size()>10)button("查看全部 "+matches.size()+" 局",()->{body.removeAllViews();heading("历史记录");for(int i=matches.size()-1;i>=0;i--)matchLine(matches.get(i));});}
    private void matchLine(JSONObject m){paragraph(("win".equals(m.optString("result"))?"胜":"负")+" · "+("skills".equals(m.optString("mode"))?"秘术":"普通")+" · "+date(m.optLong("ended")));note("时长 "+Math.max(0,(m.optLong("ended")-m.optLong("started"))/1000)+"秒 · 吃子 "+m.optInt("captures")+" · 秘术 "+m.optInt("skills")+"\n对局ID "+m.optString("id"));}
    private void timeline(JSONObject d){heading("棋 士 生 涯");ArrayList<JSONObject> entries=new ArrayList<>();JSONObject e=new JSONObject();CareerRules.put(e,"at",d.optLong("created"));CareerRules.put(e,"label",d.optBoolean("cloud")?"注册棋士账号":"建立本地棋士档案");entries.add(e);ArrayList<JSONObject> ms=CareerRules.orderedMatches(d);if(!ms.isEmpty()){addEvent(entries,ms.get(0).optLong("ended"),"首次完成对局");for(JSONObject m:ms)if("win".equals(m.optString("result"))){addEvent(entries,m.optLong("ended"),"首次获得胜利");break;}}for(CareerRules.Achievement a:CareerRules.ACHIEVEMENTS){JSONObject st=CareerRules.object(CareerRules.object(d,"achievements"),a.id);if(st.optBoolean("unlocked"))addEvent(entries,st.optLong("at"),"达成 "+a.name+" · "+a.quality);}JSONObject milestones=CareerRules.object(d,"milestones");Iterator<String> milestonesKeys=milestones.keys();while(milestonesKeys.hasNext()){JSONObject row=milestones.optJSONObject(milestonesKeys.next());addEvent(entries,row.optLong("at"),row.optString("label"));}Collections.sort(entries,(a,b)->Long.compare(b.optLong("at"),a.optLong("at")));for(JSONObject row:entries){paragraph(row.optString("label"));note(date(row.optLong("at")));}note("同一事件由固定成就ID去重；等级与羁绊奖励可在衣橱查看。");}
    private void addEvent(ArrayList<JSONObject> list,long at,String label){JSONObject e=new JSONObject();CareerRules.put(e,"at",at);CareerRules.put(e,"label",label);list.add(e);}
    private void accountPage(JSONObject d){heading("账 号 与 云 存 档");paragraph(cloud.status);note(cloud.endpoint().isEmpty()?"尚未部署云函数。当前仅使用本地JSON；卸载会删除未备份档案。":"接口："+cloud.endpoint()+"\n会话由Android Keystore加密，不保存明文密码。网络失败保留本地更改并自动重试。");button("配置HTTPS云函数地址",()->{EditText url=input("https://你的云函数地址",false);url.setText(cloud.endpoint());dialog("云端接口设置",new EditText[]{url},()->{cloud.endpoint(url.getText().toString());render();});});button("注册云端账号",()->login(true));button("登录 / 恢复云端档案",()->login(false));button("创建本地棋士",()->create(false));button("本地游客模式",()->create(true));if(d==null)return;
        button("立即重新同步",()->cloud.sync((value,error)->{if(error!=null)message(error);render();}));if(cloud.conflictRemote!=null)button("解决多设备修订冲突",()->new AlertDialog.Builder(host).setTitle("不会静默覆盖新数据").setMessage("不同棋局按ID合并。请选择昵称、好友列表和装扮采用哪一份；同局内容冲突时拒绝自动合并。").setPositiveButton("保留本机资料",(a,w)->resolve(true)).setNeutralButton("采用云端资料",(a,w)->resolve(false)).setNegativeButton("稍后",null).show());button("修改云端密码",()->{EditText old=input("原密码",true),next=input("新密码（10～128字符）",true),confirm=input("再次输入新密码",true);dialog("修改密码",new EditText[]{old,next,confirm},()->{if(!next.getText().toString().equals(confirm.getText().toString()))throw new Exception("两次密码不一致");cloud.password(old.getText().toString(),next.getText().toString(),(v,e)->{message(e==null?"密码已修改，其他设备会话已失效":e);render();});});});button("退出登录（保留本地离线档案）",()->cloud.logout((v,e)->{message(cloud.status);job(()->{store.create("游客",true);render();});}));button("导出当前档案备份",()->{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TEXT,d.toString());host.startActivity(Intent.createChooser(intent,"保存你的私密档案备份"));});note("本地备份不含密码或访问令牌，但包含好友及战绩，请自行妥善保存。云端恢复仅能恢复成功同步过的资料。");}
    private void resolve(boolean local){cloud.resolve(local,(r,e)->{message(e==null?"已合并，请再次同步":e);render();});}
    private void login(boolean register){EditText name=input("4～32位账号",false),pass=input("密码（10～128字符）",true),again=input("确认密码",true);dialog(register?"注册云端账号":"登录云端账号",register?new EditText[]{name,pass,again}:new EditText[]{name,pass},()->{if(register&&!pass.getText().toString().equals(again.getText().toString()))throw new Exception("两次密码不一致");cloud.authenticate(register,name.getText().toString().trim(),pass.getText().toString(),(r,e)->{pass.setText("");again.setText("");if(e!=null){message(e);render();return;}if(r.has("pendingLocal"))new AlertDialog.Builder(host).setTitle("本机有未同步修改").setMessage("合并不同对局记录，并选择保留哪份资料与装扮。").setPositiveButton("本机资料",(a,w)->cloud.restoreWithLocal(r,true,(v,error)->{if(error!=null)message(error);render();})).setNeutralButton("云端资料",(a,w)->cloud.restoreWithLocal(r,false,(v,error)->{if(error!=null)message(error);render();})).setNegativeButton("取消",null).show();else render();});});}
    private String rate(int wins,int games){return games==0?"—":String.format(Locale.CHINA,"%.1f%%",wins*100f/games);}
    private final class HonorSeal extends View {
        final CareerRules.Achievement achievement;final boolean unlocked;final Paint p=new Paint(3);
        HonorSeal(CareerRules.Achievement a,boolean on){super(host);achievement=a;unlocked=on;setContentDescription((on?a.name:"未解锁荣誉")+" · "+a.quality);}
        @Override protected void onDraw(Canvas canvas){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.82f;int color=!unlocked?0xff667a81:"传说".equals(achievement.quality)?0xffe8bf75:"史诗".equals(achievement.quality)?0xffbca6d8:"稀有".equals(achievement.quality)?0xff9cc9df:0xffa5c6b4;Path edge=new Path();for(int i=0;i<8;i++){double angle=Math.PI*2*i/8-Math.PI/2;float xx=x+(float)Math.cos(angle)*r,yy=y+(float)Math.sin(angle)*r;if(i==0)edge.moveTo(xx,yy);else edge.lineTo(xx,yy);}edge.close();p.setStyle(Paint.Style.FILL);p.setColor(GameDesign.alpha(color,26));canvas.drawPath(edge,p);p.setStyle(Paint.Style.STROKE);p.setColor(color);p.setStrokeWidth(dp(1));canvas.drawPath(edge,p);canvas.drawLine(x-r*.45f,y+r*.45f,x+r*.45f,y+r*.45f,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(GameDesign.EMPHASIS);p.setTextSize(r*.52f);String glyph=unlocked?achievement.name.substring(0,2):"未启";canvas.drawText(glyph,x,y-(p.ascent()+p.descent())/2,p);}
    }
    private final class PortraitBanner extends View {
        final JSONObject doc;final CharacterPortraits portraits;final Paint paint=new Paint(3);PortraitBanner(JSONObject d){super(host);doc=d;portraits=new CharacterPortraits(host);setContentDescription("角色头像与已装备头像框预览");}
        @Override protected void onDraw(Canvas c){super.onDraw(c);String wall=CareerRules.object(doc,"outfit").optString("wall");int avatar=CareerRules.object(doc,"profile").optInt("avatar");int hero=wall.startsWith("hero")?Integer.parseInt(wall.substring(4)):avatar;int accent=GameDesign.factionLights()[hero];paint.setColor("jade".equals(CareerRules.object(doc,"outfit").optString("card"))?0xff203e38:wall.startsWith("hero")?GameDesign.alpha(accent,35):0x60314b5e);c.drawRoundRect(0,0,getWidth(),getHeight(),dp(9),dp(9),paint);float size=Math.min(getHeight()*.86f,getWidth()*.44f),left=dp(14),top=(getHeight()-size)/2;RectF face=new RectF(left,top,left+size,top+size);portraits.draw(c,avatar,face,255,paint);String frame=CareerRules.object(doc,"outfit").optString("frame");paint.setColor(frame.equals("legend")?0xffffd47e:frame.equals("jade")?0xff98cbb1:frame.equals("gold")?0xffdbc28c:0xff8c9a9b);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(frame.equals("legend")?3:1));c.drawOval(face,paint);paint.setStyle(Paint.Style.FILL);paint.setTextSize(dp(17));paint.setTypeface(GameDesign.EMPHASIS);paint.setColor(gold);c.drawText(CareerRules.HEROES[avatar],left+size+dp(14),getHeight()*.45f,paint);paint.setTextSize(dp(12));paint.setColor(muted);c.drawText("四方落子 · 棋会天下",left+size+dp(14),getHeight()*.66f,paint);}
    }
}
